export interface RuleContext<Options extends { Code: unknown }> {
  sourceCode: Options["Code"];

  report(violation: object): void;
}

export interface RuleDefinition<Options extends { Code: unknown }> {
  meta?: RulesMeta<Options["Code"]>;

  create(context: RuleContext<Options>): object;
}

export interface RulesMeta<Code> {
  docs?: object | undefined;
}
